<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/constants.php'; require_once __DIR__.'/../includes/auth.php'; requireRole(ROLE_ADMIN); $db=Database::getConnection();
$summary=$db->query("SELECT COUNT(*) total_incidents,COALESCE(SUM(estimated_delay_minutes),0) total_delay,COALESCE(AVG(estimated_delay_minutes),0) avg_delay,SUM(violation_status='Verified Violation') violations,COUNT(DISTINCT order_id) delayed_deliveries FROM delivery_incident")->fetch(PDO::FETCH_ASSOC);
$totalDeliveries=(int)$db->query("SELECT COUNT(*) FROM `order` WHERE completion_status IN ('In Transit','Completed')")->fetchColumn(); $delayRate=$totalDeliveries?((int)$summary['delayed_deliveries']/$totalDeliveries*100):0;
$causes=$db->query("SELECT incident_type,COUNT(*) total,ROUND(AVG(estimated_delay_minutes),1) avg_delay FROM delivery_incident GROUP BY incident_type ORDER BY total DESC,incident_type")->fetchAll(PDO::FETCH_ASSOC);
$drivers=$db->query("SELECT d.driver_id,d.full_name,COUNT(di.incident_id) incident_count,COALESCE(ROUND(AVG(di.estimated_delay_minutes),1),0) avg_delay,SUM(di.violation_status='Verified Violation') violations FROM driver d LEFT JOIN delivery_incident di ON di.driver_id=d.driver_id GROUP BY d.driver_id,d.full_name HAVING incident_count>0 ORDER BY violations DESC,incident_count DESC")->fetchAll(PDO::FETCH_ASSOC);
require_once __DIR__.'/../includes/header.php';
?>
<style>.page{max-width:1300px;margin:25px auto;padding:0 18px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.kpi,.panel{background:var(--color-surface,#fff);border:1px solid var(--color-border,#ddd);border-radius:12px;padding:18px}.kpi strong{font-size:1.7rem;display:block;margin-top:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:18px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--color-border,#ddd)}@media(max-width:900px){.cards,.grid{grid-template-columns:1fr}}</style><div class="page"><h1>Delivery Delay Analytics</h1><p>Management view of delivery delay causes, estimated delay duration, and verified driver violations.</p><div class="cards"><div class="kpi">Incidents<strong><?=(int)$summary['total_incidents']?></strong></div><div class="kpi">Delayed Deliveries<strong><?=(int)$summary['delayed_deliveries']?></strong></div><div class="kpi">Delay Rate<strong><?=number_format($delayRate,1)?>%</strong></div><div class="kpi">Avg. Delay<strong><?=number_format((float)$summary['avg_delay'],1)?> min</strong></div><div class="kpi">Verified Violations<strong><?=(int)$summary['violations']?></strong></div></div><div class="grid"><div class="panel"><h2>Common Delay Causes</h2><table><tr><th>Cause</th><th>Reports</th><th>Avg Delay</th></tr><?php foreach($causes as $r):?><tr><td><?=htmlspecialchars($r['incident_type'])?></td><td><?=(int)$r['total']?></td><td><?=number_format((float)$r['avg_delay'],1)?> min</td></tr><?php endforeach;?></table></div><div class="panel"><h2>Driver Performance / Incidents</h2><table><tr><th>Driver</th><th>Incidents</th><th>Avg Delay</th><th>Violations</th></tr><?php foreach($drivers as $r):?><tr><td><?=htmlspecialchars($r['full_name'])?></td><td><?=(int)$r['incident_count']?></td><td><?=number_format((float)$r['avg_delay'],1)?> min</td><td><?=(int)$r['violations']?></td></tr><?php endforeach;?></table></div></div></div>
